import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import api from '../services/api';
import EventCard from '../components/EventCard';
import LoadingSpinner from '../components/LoadingSpinner';

const Home = () => {
    const [featuredEvents, setFeaturedEvents] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        fetchFeaturedEvents();
    }, []);

    const fetchFeaturedEvents = async () => {
        try {
            const response = await api.get('/events?limit=3');
            setFeaturedEvents(response.data.events);
        } catch (error) {
            console.error('Error fetching featured events:', error);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="min-h-screen bg-gray-50">
            {/* Hero Section */}
            <div className="bg-gradient-to-r from-purple-600 to-blue-600 text-white">
                <div className="container mx-auto px-4 py-20">
                    <h1 className="text-5xl font-bold mb-6">
                        Discover Amazing Events
                    </h1>
                    <p className="text-xl mb-8 max-w-2xl">
                        Find and register for the best events in your area. From tech conferences to networking meetups, we've got you covered.
                    </p>
                    <Link
                        to="/events"
                        className="bg-white text-purple-600 px-8 py-4 rounded-lg text-lg font-semibold hover:bg-gray-100 transition inline-block"
                    >
                        Browse All Events
                    </Link>
                </div>
            </div>

            {/* Featured Events */}
            <div className="container mx-auto px-4 py-16">
                <h2 className="text-3xl font-bold mb-8 text-gray-800">
                    Featured Events
                </h2>

                {loading ? (
                    <LoadingSpinner />
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                        {featuredEvents.map(event => (
                            <EventCard key={event._id} event={event} />
                        ))}
                    </div>
                )}
            </div>

            {/* Stats Section */}
            <div className="bg-white py-16">
                <div className="container mx-auto px-4">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-8 text-center">
                        <div>
                            <div className="text-4xl font-bold text-purple-600 mb-2">500+</div>
                            <div className="text-gray-600">Events Hosted</div>
                        </div>
                        <div>
                            <div className="text-4xl font-bold text-purple-600 mb-2">10,000+</div>
                            <div className="text-gray-600">Happy Attendees</div>
                        </div>
                        <div>
                            <div className="text-4xl font-bold text-purple-600 mb-2">50+</div>
                            <div className="text-gray-600">Cities Covered</div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Home;
